def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        if N == 2:
            print("2 1")
        else:
            res = [2] + [1] + list(range(3, N+1))
            print(' '.join(map(str, res)))

if __name__ == '__main__':
    main()
